/** RHEED camera: pull a frame on demand, or subscribe to the live feed. */
export class RheedCameraClient {
  static readonly target = "rheed.camera";
  constructor(private t: LumiTransport) {}

  /** Latest frame. */
  async image(): Promise<Response<ImageMeta>> {
    return this.t.call<Response<ImageMeta>>(RheedCameraClient.target, "image", {});
  }

  /** rheed.camera.get_camera_config */
  async get_camera_config(): Promise<CameraConfig> {
    return this.t.call<CameraConfig>(RheedCameraClient.target, "get_camera_config", {});
  }

  /** Partial update; omitted fields are left alone. */
  async update_camera_config(req: CameraConfig): Promise<Ack> {
    return this.t.call<Ack>(RheedCameraClient.target, "update_camera_config", req);
  }

  /** Subscribe to frame. Returns a key for unsubscribe(). */
  onFrame(handler: (meta: ImageMeta, payload: Uint8Array) => void): string {
    return this.t.subscribe(RheedCameraClient.target, "frame", handler);
  }

  unsubscribe(key: string): void {
    this.t.unsubscribe(key);
  }

  async startStreaming(): Promise<void> {
    await this.t.controlCall(RheedCameraClient.target, "start");
  }

  async stopStreaming(): Promise<void> {
    await this.t.controlCall(RheedCameraClient.target, "stop");
  }

  async getState(): Promise<CameraState> {
    return this.t.controlCall<CameraState>(RheedCameraClient.target, "state");
  }
}

