  /** experiment.driver.cool_down */
  async cool_down(req: CoolDown): Promise<TaskAck> {
    return this.t.call<TaskAck>(ExperimentDriverClient.target, "cool_down", req);
  }

  /** experiment.driver.perform_preablation */
